import{c as a,$ as o,Q as e,j as i,g as l,o as r,n,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"Розничные продажи (Чеки и касса)","description":"Оформление продаж через кассовый терминал, учет каналов сбыта, расчет логистики, формирование товарных чеков и рейтинг окупаемости времени мастера в ОмниКрафт ЕРП.","frontmatter":{"title":"Розничные продажи (Чеки и касса)","description":"Оформление продаж через кассовый терминал, учет каналов сбыта, расчет логистики, формирование товарных чеков и рейтинг окупаемости времени мастера в ОмниКрафт ЕРП.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":9},"headers":[],"relativePath":"ru/docs/spaces/production/sales.md","filePath":"ru/docs/spaces/production/sales.md","lastUpdated":1794700800000}'),c={name:"ru/docs/spaces/production/sales.md"},p={id:"продажи-кассовыи-терминал-чеки-и-окупаемость-времени",tabindex:"-1"};function g(h,t,u,f,v,m){const s=o("DocIcon");return e(),i("div",null,[l("h1",p,[r(s,{name:"sales"}),t[0]||(t[0]=n(" Продажи: Кассовый терминал, чеки и окупаемость времени ",-1)),t[1]||(t[1]=l("a",{class:"header-anchor",href:"#продажи-кассовыи-терминал-чеки-и-окупаемость-времени","aria-label":'Permalink to "Продажи: Кассовый терминал, чеки и окупаемость времени"'},"​",-1))]),t[2]||(t[2]=d('<p>В ремесленном деле и штучном производстве момент продажи — это главное подтверждение ценности труда мастера. Именно здесь овеществленный капитал, замороженный в готовых изделиях на складе, трансформируется в живую денежную ликвидность мастерской.</p><p>Если учет продаж ведется небрежно — в блокноте, сообщениях мессенджера или по банковским выпискам, — создатель неизбежно попадает в финансовую слепую зону. Забываются расходы на доставку, теряется учет списанной тары и подарочных коробок, размывается реальная маржинальность по разным торговым площадкам, а главное — мастер не видит, какие изделия действительно приносят доход, а какие лишь отнимают драгоценные рабочие часы.</p><p>Вкладка <strong>«Продажи»</strong> в <strong>ОмниКрафт ЕРП</strong> представляет собой профессиональный кассовый терминал мастерской. Она связывает склад готовой продукции, расход упаковочных материалов, кассу движения денежных средств (ДДС), каналы сбыта и глубокую аналитику окупаемости времени в единую сквозную транзакцию.</p><hr><h2 id="верхняя-инфопанель-финансовыи-пульс-мастерскои" tabindex="-1">Верхняя инфопанель: Финансовый пульс мастерской <a class="header-anchor" href="#верхняя-инфопанель-финансовыи-пульс-мастерскои" aria-label="Permalink to &quot;Верхняя инфопанель: Финансовый пульс мастерской&quot;">​</a></h2><p>В верхней части экрана расположены три сводные карточки, отражающие совокупный торговый оборот предприятия:</p><ul><li><strong>«Выручка» (зеленый индикатор):</strong> общий объем входящих денежных средств от реализации продукции за все время работы мастерской.</li><li><strong>«Себестоимость» (красный индикатор):</strong> фактическая сумма замороженных затрат (сырье, накладные расходы, упаковка и оплата времени) списанных со склада изделий.</li><li><strong>«Чистая прибыль» (акцентный индикатор):</strong> реальный финансовый результат — чистый доход создателя после вычета производственной себестоимости и прямых расходов на логистику.</li></ul><p>Непосредственно под карточками расположены кнопки оперативного управления:</p><ul><li><strong>«Новая продажа»:</strong> разворачивает компактную форму кассового терминала для оформления новой сделки.</li><li><strong>«Рейтинг маржинальности»:</strong> выдвигает боковую аналитическую панель окупаемости рабочего времени.</li></ul><hr><h2 id="оформление-сделки-в-кассовом-терминале" tabindex="-1">Оформление сделки в кассовом терминале <a class="header-anchor" href="#оформление-сделки-в-кассовом-терминале" aria-label="Permalink to &quot;Оформление сделки в кассовом терминале&quot;">​</a></h2><p>Чтобы зарегистрировать продажу, нажмите кнопку <strong>«Новая продажа»</strong>. Откроется форма кассы мастерской со следующими полями:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Выбор изделия:</strong> выпадающий список содержит только те позиции, которые физически присутствуют на складе готовой продукции (<code>остаток &gt; 0</code>). Это исключает случайную продажу отсутствующих товаров.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Канал продаж:</strong> площадка или источник сделки (например, личный сайт, социальные сети, маркетплейс, городская ярмарка или прямая продажа в мастерской).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Дата сделки:</strong> календарное поле с выбором даты. При регистрации сегодняшней продажи программа фиксирует текущее системное время; при внесении прошлых сделок автоматически выставляется полдень (12:00:00).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Количество:</strong> число реализуемых единиц. Программа проверяет доступный складской остаток и страхует от ввода отрицательных или нулевых значений.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Доставка и выбор плательщика:</strong> стоимость транспортных услуг и указание стороны, несущей логистические расходы.</div></li></ul><p>После заполнения реквизитов мастер нажимает кнопку <strong>«Продать»</strong>. Программа моментально выполняет комплексную транзакцию и выводит на экран сформированный товарный чек.</p><hr><h2 id="экономика-логистики-два-режима-учета-доставки" tabindex="-1">Экономика логистики: Два режима учета доставки <a class="header-anchor" href="#экономика-логистики-два-режима-учета-доставки" aria-label="Permalink to &quot;Экономика логистики: Два режима учета доставки&quot;">​</a></h2><p>Транспортные расходы — одна из самых частых причин скрытых убытков в малом бизнесе. ОмниКрафт ЕРП разделяет товарные потоки и оплату доставки, поддерживая два сценария:</p><ol><li><p><strong>Режим «Платит Клиент» (Покупатель):</strong></p><ul><li>Покупатель оплачивает стоимость изделия и отдельно компенсирует пересылку (например, <code>5 000 ₽</code> за сумку и <code>500 ₽</code> за доставку).</li><li>В кассу ДДС записывается общий приход <code>5 500 ₽</code> по категории «Продажи».</li><li>В кассе ДДС синхронно формируется расходная операция на <code>500 ₽</code> по категории «Доставка» (оплата услуг курьера или транспортной компании).</li><li><em>Влияние на прибыль:</em> нулевое. Прибыль рассчитывается строго от цены изделия, но касса мастерской отражает абсолютно точный оборот реальных денег.</li></ul></li><li><p><strong>Режим «Платит Мастерская» (Расход мастерской):</strong></p><ul><li>Мастер предоставил клиенту бесплатную доставку по маркетинговой акции или взял расходы на себя.</li><li>В кассу ДДС зачисляется стоимость изделия (<code>5 000 ₽</code>).</li><li>В кассе ДДС проводится расход на доставку (<code>500 ₽</code>).</li><li><em>Влияние на прибыль:</em> отрицательное. Стоимость пересылки <strong>напрямую вычитается из чистой прибыли</strong> по данной сделке.</li></ul></li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Экономика сделки</span><div class="formula-heading">Расчет чистой прибыли от продажи с учетом логистики и упаковки</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Чистая прибыль</span><span class="math-op">=</span><span class="math-var">(Цена продажи − Себестоимость единицы − Упаковка)</span><span class="math-op">×</span><span class="math-var">Количество</span><span class="math-op">−</span><span class="math-var">Доставка (если за счет мастерской)</span></div></div></div><hr><h2 id="управление-каналами-сбыта-и-индивидуальные-наценки" tabindex="-1">Управление каналами сбыта и индивидуальные наценки <a class="header-anchor" href="#управление-каналами-сбыта-и-индивидуальные-наценки" aria-label="Permalink to &quot;Управление каналами сбыта и индивидуальные наценки&quot;">​</a></h2><p>Разные торговые площадки диктуют свои правила: маркетплейсы удерживают комиссии за эквайринг и логистику, ярмарки требуют оплаты аренды стола, а личный сайт обеспечивает максимальную рентабельность.</p><p>Чтобы открыть окно настройки каналов сбыта, нажмите кнопку-шестеренку рядом с выпадающим списком каналов в кассовом терминале.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Наименование канала:</strong><br> Торговая площадка или источник заказа (например, «Авито», «Озон», ярмарка, личный сайт). </div></li><li><span class="craft-list-bullet"></span><div><strong>Индивидуальная наценка площадки:</strong><br> Процентная надбавка (+% к базовой цене) для автоматической компенсации комиссий и эквайринга. </div></li><li><span class="craft-list-bullet"></span><div><strong>Реестр активных каналов:</strong><br> Управление списком каналов с возможностью редактирования параметров и удаления неактивных. </div></li></ul><h3 id="иерархия-розничного-ценообразования" tabindex="-1">Иерархия розничного ценообразования: <a class="header-anchor" href="#иерархия-розничного-ценообразования" aria-label="Permalink to &quot;Иерархия розничного ценообразования:&quot;">​</a></h3><p>Программа определяет итоговую цену продажи в кассе по строгому алгоритму:</p><ol><li><strong>Фиксированная цена из матрицы каналов:</strong> если для данного изделия в базе задана твердая цена реализации для конкретного канала (например, ровно <code>4 500 ₽</code> для сайта), система подставит именно ее.</li><li><strong>Динамический расчет по калькулятору:</strong> если фиксированная цена не задана, программа берет себестоимость единицы, применяет наценку изделия (или глобальную наценку пространства) и прибавляет процентную наценку выбранного канала сбыта.</li></ol><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Компенсация комиссий торговых площадок</p><p>Используйте процентные наценки каналов для автоматической компенсации издержек. Если маркетплейс взимает комиссию 20%, установите в свойствах этого канала наценку <code>+25%</code>. Это позволит сохранить желаемую чистую маржу без необходимости вручную пересчитывать ценники на каждое изделие.</p></div><hr><h2 id="электронныи-товарныи-чек-и-клиентскии-сервис" tabindex="-1">Электронный товарный чек и клиентский сервис <a class="header-anchor" href="#электронныи-товарныи-чек-и-клиентскии-сервис" aria-label="Permalink to &quot;Электронный товарный чек и клиентский сервис&quot;">​</a></h2><p>Сразу после проведения сделки программа открывает диалоговое окно товарного чека. Чек также можно в любой момент открыть повторно из журнала истории продаж.</p><p>Содержимое электронного товарного чека:</p><ul><li>Точная дата и время проведения операции;</li><li>Канал реализации;</li><li>Наименование изделия и количество штук;</li><li>Розничная цена единицы и итоговая стоимость;</li><li>Информация о доставке и плательщике;</li><li>Общая сумма к оплате.</li></ul><p>Если в программе активирован модуль «Амбассадор», в нижней части чека автоматически формируется ненавязчивый фирменный блок с персональной ссылкой мастера.</p><p>Нажмите кнопку <strong>«Скопировать чек»</strong>, чтобы мгновенно перенести готовый текст чека в буфер обмена. Его можно сразу вставить в переписку с заказчиком в Telegram, WhatsApp или личных сообщениях социальной сети, обеспечив высокий уровень доверия и прозрачности.</p><hr><h2 id="журнал-продаж-операционныи-реестр-чеков" tabindex="-1">Журнал продаж: Операционный реестр чеков <a class="header-anchor" href="#журнал-продаж-операционныи-реестр-чеков" aria-label="Permalink to &quot;Журнал продаж: Операционный реестр чеков&quot;">​</a></h2><p>В левой нижней части экрана расположен хронологический журнал всех проведенных сделок:</p><ul><li><strong>Столбцы таблицы:</strong> Дата сделки, Канал продаж, Изделие, Количество, Чистая прибыль и кнопка открытия чека (иконка документа).</li><li><strong>Постраничный просмотр (пагинация):</strong> журнал выводит по 20 строк на страницу. Это гарантирует мгновенный отклик и плавную прокрутку даже при базе в десятки тысяч чеков.</li><li><strong>Быстрый доступ к деталям:</strong> клик по иконке чека в строке таблицы открывает карточку продажи для сверки данных или повторной отправки клиенту.</li></ul><hr><h2 id="аналитика-реитинг-изделии-по-окупаемости-времени" tabindex="-1">Аналитика: Рейтинг изделий по окупаемости времени <a class="header-anchor" href="#аналитика-реитинг-изделии-по-окупаемости-времени" aria-label="Permalink to &quot;Аналитика: Рейтинг изделий по окупаемости времени&quot;">​</a></h2><p>В правой части экрана расположена боковая панель <strong>«Рейтинг изделий по окупаемости времени»</strong> (вызывается кнопкой <strong>«Рейтинг маржинальности»</strong>).</p><p>Большинство учетных таблиц показывают предпринимателю только абсолютную прибыль (например: <em>«на кожаном портфеле заработано 6 000 ₽, а на ключнице — 900 ₽»</em>). Это формирует ложное впечатление, что мастерской выгоднее изготавливать крупные и дорогие вещи.</p><p>ОмниКрафт ЕРП рассчитывает ключевую метрику ремесленной эффективности — <strong>прибыль за час рабочего времени мастера</strong>.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Экономическая аналитика</span><div class="formula-heading">Окупаемость рабочего времени (Прибыль за час труда)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Прибыль за час</span><span class="math-op">=</span><span class="math-var">Совокупная чистая прибыль по проданным единицам</span><span class="math-op">÷</span><span class="math-var">(Количество проданных единиц × Норма времени мастера)</span></div></div></div><h3 id="практические-выводы-для-владельца-мастерскои" tabindex="-1">Практические выводы для владельца мастерской: <a class="header-anchor" href="#практические-выводы-для-владельца-мастерскои" aria-label="Permalink to &quot;Практические выводы для владельца мастерской:&quot;">​</a></h3><p>Представьте анализ реальной статистики продаж:</p><ul><li><strong>Дорожная сумка:</strong> чистая прибыль <code>5 000 ₽</code>, но чистое время изготовления составляет <code>12.5</code> часов. Доходность мастера: <code>400 ₽ в час</code>.</li><li><strong>Классический ремень:</strong> чистая прибыль <code>1 800 ₽</code>, время изготовления — <code>1.2</code> часа. Доходность мастера: <code>1 500 ₽ в час</code>.</li><li><strong>Минималистичный картхолдер:</strong> чистая прибыль <code>900 ₽</code>, время раскроя и сборки — <code>0.4</code> часа (24 минуты). Доходность мастера: <code>2 250 ₽ в час</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Цеховой вывод</p><p>Панель окупаемости времени наглядно показывает «скрытых пожирателей времени» и золотые жилы ассортимента. Если трудоемкое флагманское изделие приносит меньше дохода в час, чем базовые аксессуары, мастеру необходимо либо повышать на него цену в Калькуляторе, либо оптимизировать технологические операции раскроя и сборки.</p></div><hr><h2 id="сводная-матрица-финансово-складских-проводок-сделки" tabindex="-1">Сводная матрица финансово-складских проводок сделки <a class="header-anchor" href="#сводная-матрица-финансово-складских-проводок-сделки" aria-label="Permalink to &quot;Сводная матрица финансово-складских проводок сделки&quot;">​</a></h2><p>В секунду нажатия кнопки <strong>«Продать»</strong> программа выполняет атомарную транзакцию в базе данных SQLite:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Контур системы</th><th style="text-align:left;">Выполняемое действие</th><th style="text-align:left;">Результат для мастерской</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Склад готовой продукции</strong></td><td style="text-align:left;">Списание остатка изделия (<code>-X шт.</code>)</td><td style="text-align:left;">Актуализация физического наличия на полке</td></tr><tr><td style="text-align:left;"><strong>Партии готовых товаров</strong></td><td style="text-align:left;">Списание ранних партий по методу первых партий (ФИФО)</td><td style="text-align:left;">Фиксация исторической себестоимости проданных единиц</td></tr><tr><td style="text-align:left;"><strong>Склад материалов (сырье)</strong></td><td style="text-align:left;">Автоматическое списание упаковочных материалов</td><td style="text-align:left;">Коробки, бирки и тишью списываются по нормам техкарты</td></tr><tr><td style="text-align:left;"><strong>Касса движения денег (ДДС)</strong></td><td style="text-align:left;">Двойная проводка: приход выручки и расход на логистику</td><td style="text-align:left;">Абсолютная точность живых денег в кассе</td></tr><tr><td style="text-align:left;"><strong>Журнал продаж (журнал продаж)</strong></td><td style="text-align:left;">Запись несгораемого слепка сделки</td><td style="text-align:left;">Сохранение исторических данных для аналитики</td></tr><tr><td style="text-align:left;"><strong>Управленческий капитал</strong></td><td style="text-align:left;">Переток: Товарный запас ➔ Денежные средства + Прибыль</td><td style="text-align:left;">Рост чистых активов и финансовой устойчивости бизнеса</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Физика учета: Почему упаковка списывается при продаже</p><p>Упаковочные материалы (брендированные коробки, ленты, сургучные печати, защитная бумага) бронируются в рецепте Калькулятора, но <strong>не списываются при сборке изделия на Верстаке</strong>. Изделие хранится на полке без финальной тары, чтобы коробка не пылилась и не мялась при хранении. В момент нажатия кнопки <strong>«Продать»</strong> программа автоматически находит привязанный комплект упаковки и безвозвратно списывает нужные материалы со склада сырья.</p></div><div class="warning custom-block"><p class="custom-block-title">Оформление подарков и продаж со 100% скидкой</p><p>Если Вы подарили изделие блогеру для рекламы, передали другу или предоставили клиенту скидку 100%, <strong>никогда не списывайте его через инвентаризацию как недостачу</strong>. Всегда оформляйте сделку через кассовый терминал с ценой <code>0 ₽</code>. В этом случае себестоимость изделия будет честно зафиксирована в финансовом отчете как коммерческий расход на маркетинг, а складской и партионный учет сохранит абсолютную чистоту.</p></div>',55))])}const y=a(c,[["render",g]]);export{x as __pageData,y as default};
